<?php
require __DIR__.'/config.php';
$u=require_login();$b=require_business();if($b['type']!=='event_centre'){redirect('index.php');}if(!can('events')){http_response_code(403);exit('Forbidden');}
$pdo=db();$plan=require_active_subscription((int)$b['id']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';
 if($action==='create_event'){
  $name=trim($_POST['name']??'');$date=$_POST['event_date']??'';$guests=max(1,(int)($_POST['guest_count']??0));$tables=max(1,(int)($_POST['table_count']??0));$type=$_POST['event_type']??'corporate';$venue=trim($_POST['venue']??'');$package=(int)($_POST['package_id']??0);
  if($name===''||!$date)throw new RuntimeException('Event name and date are required.');
  if(!in_array($type,['private','corporate','conference','seminar','wedding','other'],true))$type='corporate';
  if($err=plan_limit_error((int)$b['id'],'events'))throw new RuntimeException($err);if($err=plan_limit_error((int)$b['id'],'guests',$guests))throw new RuntimeException($err);
  $ps=$pdo->prepare("SELECT * FROM event_packages WHERE id=? AND status='active' LIMIT 1");$ps->execute([$package]);$pkg=$ps->fetch();if($package&&!$pkg)throw new RuntimeException('Selected event package is not available.');
  if($pkg && ($guests<(int)$pkg['min_guests'] || (!empty($pkg['max_guests'])&&$guests>(int)$pkg['max_guests'])))throw new RuntimeException('Guest count is outside the selected package range.');
  $amount=$pkg?(float)$pkg['price']:0;$pdo->beginTransaction();$pdo->prepare('INSERT INTO events(business_id,package_id,name,event_type,organiser_name,organiser_email,organiser_phone,venue,event_date,guest_count,table_count,status,amount,access_token) VALUES(?,?,?,?,?,?,?,?,?,?,?,\'scheduled\',?,?)')->execute([$b['id'],$pkg['id']??null,$name,$type,$u['name'],$u['email']??null,null,$venue,$date,$guests,$tables,$amount,random_token(24)]);$eid=(int)$pdo->lastInsertId();
  for($i=1;$i<=$tables;$i++)$pdo->prepare('INSERT INTO event_tables(event_id,table_number,capacity,qr_token) VALUES(?,?,?,?)')->execute([$eid,'Table '.$i,max(1,(int)ceil($guests/$tables)),random_token(20)]);
  $pdo->commit();audit((int)$b['id'],(int)$u['id'],'event.created',$name);flash('Event created with '.$tables.' table QR codes.');
 } elseif($action==='add_table'){$eid=(int)$_POST['event_id'];$num=trim($_POST['table_number']??'');$cap=max(1,(int)($_POST['capacity']??1));$s=$pdo->prepare('SELECT id FROM events WHERE id=? AND business_id=? LIMIT 1');$s->execute([$eid,$b['id']]);if(!$s->fetchColumn())throw new RuntimeException('Event not found.');if($err=plan_limit_error((int)$b['id'],'tables'))throw new RuntimeException($err);if($num==='')throw new RuntimeException('Table number is required.');$pdo->prepare('INSERT INTO event_tables(event_id,table_number,capacity,qr_token) VALUES(?,?,?,?)')->execute([$eid,$num,$cap,random_token(20)]);flash('Event table added.');
 } elseif($action==='add_guest'){$eid=(int)$_POST['event_id'];$name=trim($_POST['name']??'');$table=(int)($_POST['table_id']??0)?:null;if($name==='')throw new RuntimeException('Guest name is required.');if($err=plan_limit_error((int)$b['id'],'guests'))throw new RuntimeException($err);$s=$pdo->prepare('SELECT id FROM events WHERE id=? AND business_id=?');$s->execute([$eid,$b['id']]);if(!$s->fetchColumn())throw new RuntimeException('Event not found.');if($table){$s=$pdo->prepare('SELECT id FROM event_tables WHERE id=? AND event_id=?');$s->execute([$table,$eid]);if(!$s->fetchColumn())$table=null;}$pdo->prepare('INSERT INTO event_guests(event_id,table_id,name,email,phone,seat_number,invitation_token) VALUES(?,?,?,?,?,?,?)')->execute([$eid,$table,$name,trim($_POST['email']??'')?:null,trim($_POST['phone']??'')?:null,trim($_POST['seat_number']??'')?:null,random_token(24)]);flash('Guest added.');
 } elseif($action==='event_status'){$eid=(int)$_POST['event_id'];$status=$_POST['status']??'draft';if(!in_array($status,['draft','scheduled','active','completed','cancelled'],true))throw new RuntimeException('Invalid status.');$pdo->prepare('UPDATE events SET status=?,updated_at=NOW() WHERE id=? AND business_id=?')->execute([$status,$eid,$b['id']]);flash('Event status updated.');}
 elseif($action==='event_hero'){$eid=(int)$_POST['event_id'];$s=$pdo->prepare('SELECT hero_image FROM events WHERE id=? AND business_id=? LIMIT 1');$s->execute([$eid,$b['id']]);$evh=$s->fetch();if(!$evh)throw new RuntimeException('Event not found.');$newHero=hero_upload('event_hero');$s=$pdo->prepare('UPDATE events SET hero_image=?,updated_at=NOW() WHERE id=? AND business_id=?');$s->execute([$newHero,$eid,$b['id']]);delete_hero_file($evh['hero_image']??null);audit((int)$b['id'],(int)$u['id'],'event.hero_updated','Event #'.$eid.' hero image replaced');flash('Event hero image updated.');}
 elseif($action==='remove_event_hero'){$eid=(int)$_POST['event_id'];$s=$pdo->prepare('SELECT hero_image FROM events WHERE id=? AND business_id=? LIMIT 1');$s->execute([$eid,$b['id']]);$evh=$s->fetch();if(!$evh)throw new RuntimeException('Event not found.');$s=$pdo->prepare('UPDATE events SET hero_image=NULL,updated_at=NOW() WHERE id=? AND business_id=?');$s->execute([$eid,$b['id']]);delete_hero_file($evh['hero_image']??null);audit((int)$b['id'],(int)$u['id'],'event.hero_removed','Event #'.$eid.' hero image removed');flash('Event hero image removed.');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('event.php');}
$events=$pdo->prepare('SELECT e.*,p.name package_name,(SELECT COUNT(*) FROM event_tables t WHERE t.event_id=e.id AND t.status=\'active\') table_actual,(SELECT COUNT(*) FROM event_guests g WHERE g.event_id=e.id) guest_actual FROM events e LEFT JOIN event_packages p ON p.id=e.package_id WHERE e.business_id=? ORDER BY e.event_date DESC,e.id DESC');$events->execute([$b['id']]);$events=$events->fetchAll();
$packages=$pdo->query("SELECT * FROM event_packages WHERE status='active' ORDER BY sort_order,id")->fetchAll();
$selected=$events[0]['id']??0;$tables=[];$guests=[];if($selected){$s=$pdo->prepare('SELECT * FROM event_tables WHERE event_id=? ORDER BY id');$s->execute([$selected]);$tables=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM event_guests WHERE event_id=? ORDER BY id DESC LIMIT 100');$s->execute([$selected]);$guests=$s->fetchAll();}
include __DIR__.'/app/layout_top.php';?>
<div class="page-head"><div><div class="eyebrow">Event operations</div><h1>Events</h1><p>Create events, assign guests and manage table QR codes.</p></div></div>
<div class="panel"><h3>Create event</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create_event"><label>Event name<input name="name" placeholder="Annual Conference 2026" required></label><label>Event type<select name="event_type"><option value="corporate">Corporate</option><option value="conference">Conference</option><option value="seminar">Seminar</option><option value="wedding">Wedding</option><option value="private">Private</option><option value="other">Other</option></select></label><label>Date<input type="date" name="event_date" required></label><label>Guests<input type="number" name="guest_count" min="1" required></label><label>Tables<input type="number" name="table_count" min="1" required></label><label>Venue<input name="venue"></label><label>Package<select name="package_id"><option value="0">Custom</option><?php foreach($packages as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> · ₦<?=number_format((float)$p['price'],0)?> · <?=e($p['min_guests'])?>–<?=e($p['max_guests']??'∞')?></option><?php endforeach;?></select></label><button class="btn gold">Create event</button></form></div>
<div class="panel"><h3>Your events</h3><?php foreach($events as $ev):?><div class="row"><div><b><?=e($ev['name'])?></b><div class="small muted"><?=e($ev['event_date'])?> · <?=e(strtoupper($ev['event_type']))?> · <?=e($ev['package_name']??'Custom')?></div><div class="small muted">Guests <?=$ev['guest_actual']?>/<?=$ev['guest_count']?> · Tables <?=$ev['table_actual']?>/<?=$ev['table_count']?></div></div><div class="right"><span class="badge"><?=e(strtoupper($ev['status']))?></span><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="event_status"><input type="hidden" name="event_id" value="<?=$ev['id']?>"><select name="status"><option>scheduled</option><option>active</option><option>completed</option><option>cancelled</option><option>draft</option></select><button class="btn">Set</button></form></div></div><?php endforeach;if(!$events):?><p class="muted">No events yet.</p><?php endif;?></div>
<?php if($selected):?><div class="panel"><h3>Event hero image</h3><p class="small muted">Optional event-specific cover. If uploaded, it appears at the top when guests scan this event table QR. Otherwise SERV uses your business hero.</p><?php $selectedEvent=$events[array_search($selected,array_column($events,'id'))]??null;?><?php if(!empty($selectedEvent['hero_image'])):?><div class="hero-settings-preview"><img src="<?=e($selectedEvent['hero_image'])?>" alt="Event hero"><div><b>Current event hero</b><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="action" value="remove_event_hero"><input type="hidden" name="event_id" value="<?=$selected?>"><button class="btn" type="submit">Remove</button></form></div></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form-grid" style="margin-top:12px"><?=csrf_field()?><input type="hidden" name="action" value="event_hero"><input type="hidden" name="event_id" value="<?=$selected?>"><label style="grid-column:1/-1">Upload event cover<input type="file" name="event_hero" accept="image/jpeg,image/png,image/webp" required><small class="small muted">JPG, PNG or WebP · minimum 600 × 300 · recommended 1600 × 900.</small></label><div><button class="btn gold"><?=!empty($selectedEvent['hero_image'])?'Replace event hero':'Upload event hero'?></button></div></form></div>
<div class="panel"><h3>Event #<?=$selected?> · Tables & QR</h3><?php foreach($tables as $t):$url=base_url().'/q.php?et='.urlencode($t['qr_token']);?><div class="row"><div><b><?=e($t['table_number'])?></b><div class="small muted">Capacity <?=$t['capacity']?></div></div><div class="right"><img src="qr-image.php?d=<?=rawurlencode($url)?>" alt="QR" style="width:72px;height:72px;border-radius:8px"><div><a class="btn" target="_blank" href="qr-image.php?d=<?=rawurlencode($url)?>">QR</a></div></div></div><?php endforeach;?><form method="post" class="form-grid" style="margin-top:12px"><?=csrf_field()?><input type="hidden" name="action" value="add_table"><input type="hidden" name="event_id" value="<?=$selected?>"><label>Table number<input name="table_number" placeholder="Table VIP" required></label><label>Capacity<input type="number" name="capacity" min="1" value="1"></label><button class="btn gold">Add table</button></form></div>
<div class="panel"><h3>Guests</h3><?php foreach($guests as $g):?><div class="row"><div><b><?=e($g['name'])?></b><div class="small muted"><?=e($g['email']??'')?> · <?=e($g['phone']??'')?></div></div><span class="badge"><?=e(strtoupper($g['status']))?></span></div><?php endforeach;if(!$guests):?><p class="muted">No guests added yet.</p><?php endif;?><form method="post" class="form-grid" style="margin-top:12px"><?=csrf_field()?><input type="hidden" name="action" value="add_guest"><input type="hidden" name="event_id" value="<?=$selected?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email"></label><label>Phone<input name="phone"></label><label>Seat<input name="seat_number"></label><label>Table<select name="table_id"><option value="0">Unassigned</option><?php foreach($tables as $t):?><option value="<?=$t['id']?>"><?=e($t['table_number'])?></option><?php endforeach;?></select></label><button class="btn gold">Add guest</button></form></div><?php endif;?>
<?php include __DIR__.'/app/layout_bottom.php';